mapper.select:
SELECT FROM todos t JOIN plans p ON p.id = t.plan_id WHERE t.plan_id = #{planId} AND
AND t.title ILIKE '%' || #{queryPattern} || '%' ESCAPE '\'
AND t.status = #{status}
AND t.priority = #{priority}
AND EXISTS ( SELECT 1 FROM todo_tags tt JOIN tags g ON g.id = tt.tag_id WHERE tt.todo_id = t.id AND tt.tag_id = #{tagId} AND g.user_id = #{userId} AND g.deleted_at IS NULL )
AND
AND t.due_date = #{today}
AND t.due_date > #{today}
AND t.due_date IS NULL
ORDER BY
ASC, t.due_date ASC NULLS LAST, t.created_at ASC, t.id ASC
t.created_at ASC, t.id ASC
